(window.__quranSurahs=window.__quranSurahs||{})[80]={"nomPhon":"Abasa","versets":{"1":{"text":"Il s'est renfrogné et il s'est détourné","arabe":"عَبَسَ وَتَوَلَّىٰٓ"},"2":{"text":"parce que l'aveugle est venu à lui.","arabe":"أَن جَآءَهُ ٱلْأَعْمَىٰ"},"3":{"text":"Qui te dit: peut-être [cherche]-t-il à se purifier?","arabe":"وَمَا يُدْرِيكَ لَعَلَّهُۥ يَزَّكَّىٰٓ"},"4":{"text":"ou à se rappeler en sorte que le rappel lui profite?","arabe":"أَوْ يَذَّكَّرُ فَتَنفَعَهُ ٱلذِّكْرَىٰٓ"},"5":{"text":"Quant à celui qui se complaît dans sa suffisance (pour sa richesse)","arabe":"أَمَّا مَنِ ٱسْتَغْنَىٰ"},"6":{"text":"tu vas avec empressement à sa rencontre.","arabe":"فَأَنتَ لَهُۥ تَصَدَّىٰ"},"7":{"text":"Or, que t'importe qu'il ne se purifie pas».","arabe":"وَمَا عَلَيْكَ أَلَّا يَزَّكَّىٰ"},"8":{"text":"Et quant à celui qui vient à toi avec empressement","arabe":"وَأَمَّا مَن جَآءَكَ يَسْعَىٰ"},"9":{"text":"tout en ayant la crainte,","arabe":"وَهُوَ يَخْشَىٰ"},"10":{"text":"tu ne t'en soucies pas.","arabe":"فَأَنتَ عَنْهُ تَلَهَّىٰ"},"11":{"text":"N'agis plus ainsi! Vraiment ceci est un rappel -","arabe":"كَلَّآ إِنَّهَا تَذْكِرَةٌۭ"},"12":{"text":"quiconque veut, donc, s'en rappelle -","arabe":"فَمَن شَآءَ ذَكَرَهُۥ"},"13":{"text":"consigné dans des feuilles honorées,","arabe":"فِى صُحُفٍۢ مُّكَرَّمَةٍۢ"},"14":{"text":"élevées, purifiées,","arabe":"مَّرْفُوعَةٍۢ مُّطَهَّرَةٍۭ"},"15":{"text":"entre les mains d'ambassadeurs","arabe":"بِأَيْدِى سَفَرَةٍۢ"},"16":{"text":"nobles, obéissants.","arabe":"كِرَامٍۭ بَرَرَةٍۢ"},"17":{"text":"Que périsse l'homme! Qu'il est ingrat!","arabe":"قُتِلَ ٱلْإِنسَٰنُ مَآ أَكْفَرَهُۥ"},"18":{"text":"De quoi [Allah] l'a-t-Il créé?","arabe":"مِنْ أَىِّ شَىْءٍ خَلَقَهُۥ"},"19":{"text":"D'une goutte de sperme, Il le crée et détermine (son destin):","arabe":"مِن نُّطْفَةٍ خَلَقَهُۥ فَقَدَّرَهُۥ"},"20":{"text":"puis Il lui facilite le chemin;","arabe":"ثُمَّ ٱلسَّبِيلَ يَسَّرَهُۥ"},"21":{"text":"puis Il lui donne la mort et le met au tombeau;","arabe":"ثُمَّ أَمَاتَهُۥ فَأَقْبَرَهُۥ"},"22":{"text":"puis Il le ressuscitera quand Il voudra.","arabe":"ثُمَّ إِذَا شَآءَ أَنشَرَهُۥ"},"23":{"text":"Eh bien non! [L'homme] n'accomplit pas ce qu'Il lui commande.","arabe":"كَلَّا لَمَّا يَقْضِ مَآ أَمَرَهُۥ"},"24":{"text":"Que l'homme considère donc sa nourriture:","arabe":"فَلْيَنظُرِ ٱلْإِنسَٰنُ إِلَىٰ طَعَامِهِۦٓ"},"25":{"text":"C'est Nous qui versons l'eau abondante,","arabe":"أَنَّا صَبَبْنَا ٱلْمَآءَ صَبًّۭا"},"26":{"text":"puis Nous fendons la terre par fissures","arabe":"ثُمَّ شَقَقْنَا ٱلْأَرْضَ شَقًّۭا"},"27":{"text":"et y faisons pousser grains,","arabe":"فَأَنۢبَتْنَا فِيهَا حَبًّۭا"},"28":{"text":"vignobles et légumes,","arabe":"وَعِنَبًۭا وَقَضْبًۭا"},"29":{"text":"oliviers et palmiers,","arabe":"وَزَيْتُونًۭا وَنَخْلًۭا"},"30":{"text":"jardins touffus,","arabe":"وَحَدَآئِقَ غُلْبًۭا"},"31":{"text":"fruits et herbages,","arabe":"وَفَٰكِهَةًۭ وَأَبًّۭا"},"32":{"text":"pour votre jouissance vous et vos bestiaux.","arabe":"مَّتَٰعًۭا لَّكُمْ وَلِأَنْعَٰمِكُمْ"},"33":{"text":"Puis quand viendra le Fracas,","arabe":"فَإِذَا جَآءَتِ ٱلصَّآخَّةُ"},"34":{"text":"le jour où l'homme s'enfuira de son frère,","arabe":"يَوْمَ يَفِرُّ ٱلْمَرْءُ مِنْ أَخِيهِ"},"35":{"text":"de sa mère, de son père,","arabe":"وَأُمِّهِۦ وَأَبِيهِ"},"36":{"text":"de sa compagne et de ses enfants,","arabe":"وَصَٰحِبَتِهِۦ وَبَنِيهِ"},"37":{"text":"car chacun d'eux, ce jour-là, aura son propre cas pour l'occuper.","arabe":"لِكُلِّ ٱمْرِئٍۢ مِّنْهُمْ يَوْمَئِذٍۢ شَأْنٌۭ يُغْنِيهِ"},"38":{"text":"Ce jour-là, il y aura des visages rayonnants,","arabe":"وُجُوهٌۭ يَوْمَئِذٍۢ مُّسْفِرَةٌۭ"},"39":{"text":"riants et réjouis.","arabe":"ضَاحِكَةٌۭ مُّسْتَبْشِرَةٌۭ"},"40":{"text":"De même qu'il y aura, ce jour-là, des visages couverts de poussière,","arabe":"وَوُجُوهٌۭ يَوْمَئِذٍ عَلَيْهَا غَبَرَةٌۭ"},"41":{"text":"recouverts de ténèbres.","arabe":"تَرْهَقُهَا قَتَرَةٌ"},"42":{"text":"Voilà les infidèles, les libertins.","arabe":"أُو۟لَٰٓئِكَ هُمُ ٱلْكَفَرَةُ ٱلْفَجَرَةُ"}}};